function test_array_slice() {
    $exchange = new \ccxt\async\Exchange(array(
        'id' => 'sampleexchange',
    ));
    $arr = ['a', 'b', 'c', 'd', 'e', 'f'];
    // the second argument is the end index (exclusive), not a length
    assert_deep_equal($exchange, null, 'testArraySlice', $exchange->array_slice($arr, 0, 2), ['a', 'b']);
    assert_deep_equal($exchange, null, 'testArraySlice', $exchange->array_slice($arr, 2, 4), ['c', 'd']);
    assert_deep_equal($exchange, null, 'testArraySlice', $exchange->array_slice($arr, 3, 6), ['d', 'e', 'f']);
    assert_deep_equal($exchange, null, 'testArraySlice', $exchange->array_slice($arr, 2), ['c', 'd', 'e', 'f']);
    assert_deep_equal($exchange, null, 'testArraySlice', $exchange->array_slice($arr, -2), ['e', 'f']);
}
